#!/usr/bin/env python3
"""Remove JavaScript from an HTML file in place.

The file is scanned with a tokenizer modelled on the HTML5 tokenizer so that
it sees tags the same way a browser does. Only dangerous pieces are removed
(script elements, event-handler attributes, javascript:/data: URLs, ...);
every other byte of the input is left untouched.
"""
import html
import re
import sys

WS = " \t\n\r\f"

# Elements removed together with their content.
REMOVE_WITH_CONTENT = {"script", "iframe"}
# Elements whose tags are removed but whose content is kept.
REMOVE_TAG_ONLY = {"object", "embed", "applet", "frame", "frameset", "base",
                   "portal"}
# Elements whose content is raw text / RCDATA in HTML.
RAW_TEXT = {"style", "title", "textarea", "xmp", "noembed", "noframes",
            "noscript", "iframe", "plaintext"}

SAFE_DATA_RE = re.compile(
    r"data:image/(png|gif|jpe?g|webp|bmp|avif|x-icon|vnd\.microsoft\.icon)[;,]")
BAD_SCHEME_RE = re.compile(r"(java|vb|live)script:|mocha:|data:")
DROP_ATTRS = {"srcdoc"}
ANIMATION_ATTRS = {"values", "to", "from", "by"}
CSS_BAD_RE = re.compile(
    r"expression\(|(java|vb|live)script:|behavior:|-moz-binding|data:text/html|"
    r"@import")


def normalize(value):
    value = html.unescape(value)
    value = "".join(c for c in value if ord(c) > 0x20 and not 0x7f <= ord(c) <= 0x9f)
    return value.lower()


def normalize_css(value):
    value = html.unescape(value)
    value = re.sub(r"/\*.*?(\*/|$)", "", value, flags=re.S)
    value = re.sub(r"\\([0-9a-fA-F]{1,6})\s?",
                   lambda m: chr(int(m.group(1), 16)) if int(m.group(1), 16) < 0x110000 else "",
                   value)
    value = re.sub(r"\\(.)", r"\1", value, flags=re.S)
    return normalize(value)


def bad_url(value):
    v = normalize(value)
    m = BAD_SCHEME_RE.search(v)
    if not m:
        return False
    if m.start() != 0:
        return False
    return not SAFE_DATA_RE.match(v)


def bad_attr(name, value):
    n = name.lower()
    if n.startswith("on") or n in DROP_ATTRS:
        return True
    if value is None:
        return False
    if n == "style":
        return bool(CSS_BAD_RE.search(normalize_css(value)))
    if n in ANIMATION_ATTRS:
        return any(bad_url(part) for part in html.unescape(value).split(";"))
    if bad_url(value):
        return True
    v = normalize(value)
    # URL-like attributes containing a script scheme anywhere (e.g. srcset).
    if n in ("srcset", "imagesrcset", "ping") and re.search(r"(java|vb|live)script:", v):
        return True
    return False


def parse_tag(s, i):
    """Parse a start/end tag beginning at s[i] == '<'.

    Returns (end_index, name, is_end_tag, attrs) where attrs is a list of
    (remove_start, remove_end, name, value).
    """
    n = len(s)
    j = i + 1
    is_end = False
    if s[j] == "/":
        is_end = True
        j += 1
    start = j
    while j < n and s[j] not in WS and s[j] not in "/>":
        j += 1
    name = s[start:j].lower()
    attrs = []
    while True:
        ws_start = j
        while j < n and (s[j] in WS or s[j] == "/"):
            if s[j] == "/":
                ws_start = j + 1
            j += 1
        if j >= n:
            return n, name, is_end, attrs
        if s[j] == ">":
            return j + 1, name, is_end, attrs
        astart = j
        j += 1  # first char may be '=' or anything else
        while j < n and s[j] not in WS and s[j] not in "/>=":
            j += 1
        aname = s[astart:j]
        k = j
        while k < n and s[k] in WS:
            k += 1
        value = None
        if k < n and s[k] == "=":
            k += 1
            while k < n and s[k] in WS:
                k += 1
            if k < n and s[k] in "\"'":
                q = s[k]
                e = s.find(q, k + 1)
                if e == -1:
                    value = s[k + 1:]
                    k = n
                else:
                    value = s[k + 1:e]
                    k = e + 1
            elif k < n and s[k] == ">":
                value = ""
            else:
                vs = k
                while k < n and s[k] not in WS and s[k] != ">":
                    k += 1
                value = s[vs:k]
            j = k
        attrs.append((ws_start, j, aname, value))


