    out = []
    pos = i
    changed = False
    for rs, re_, aname, value in attrs:
        if bad_attr(aname, value):
            out.append(s[pos:rs])
            pos = re_
            changed = True
    out.append(s[pos:end])
    return "".join(out), changed


