                if s.startswith(">", j):
                    i = j + 1
                    continue
                if s.startswith("->", j):
                    i = j + 2
                    continue
                m = re.compile(r"--!?>").search(s, j)
                i = m.end() if m else n
                continue
            e = s.find(">", i)
            i = e + 1 if e != -1 else n
            continue
        if c == "?" and comments:
            e = s.find(">", i)
            i = e + 1 if e != -1 else n
            continue
        if c == "/" and comments and i + 2 < n and not s[i + 2].isascii():
            e = s.find(">", i)
            i = e + 1 if e != -1 else n
            continue
        is_tag = (c.isascii() and c.isalpha()) or (
            c == "/" and i + 2 < n and s[i + 2].isascii() and s[i + 2].isalpha())
        if not is_tag:
            i += 1
            continue
        end, name, is_end, attrs = parse_tag(s, i)
        out.append(s[text_start:i])
        if name in REMOVE_WITH_CONTENT or name in REMOVE_TAG_ONLY:
            if not is_end and name in REMOVE_WITH_CONTENT:
                close = find_end_tag(s, end, name)
                if close >= n:
                    end = n
                else:
                    end, _, _, _ = parse_tag(s, close)
            i = text_start = end
            continue
        if name == "meta" and not is_end:
            vals = {a[2].lower(): a[3] for a in reversed(attrs)}
            if (vals.get("http-equiv") or "").strip().lower() == "refresh" and \
                    re.search(r"(java|vb|live)script:|data:", normalize(vals.get("content") or "")):
                i = text_start = end
                continue
        tag, _ = rebuild_tag(s, i, end, attrs)
        out.append(tag)
        i = text_start = end
        if not is_end and name in RAW_TEXT:
            close = find_end_tag(s, end, name)
            inner = s[end:close]
            if name == "style" and CSS_BAD_RE.search(normalize_css(inner)):
                inner = ""
            else:
                inner = sanitize(inner, comments=False)
            out.append(inner)
            i = text_start = close
    out.append(s[text_start:])
    return "".join(out)


def main():
    if len(sys.argv) < 2:
        print("usage: filter.py FILE.html", file=sys.stderr)
        sys.exit(1)
    path = sys.argv[1]
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")
    result = text
    for _ in range(50):
        new = sanitize(result)
        if new == result:
            break
        result = new
    if result != text:
        with open(path, "wb") as f:
            f.write(result.encode("utf-8", errors="surrogateescape"))


